def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def pos(val, default=(0, 0)):
        if isinstance(val, (list, tuple)) and len(val) >= 2:
            return val[0], val[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def nearest(start, items):
        best = None
        best_d = None
        for it in items:
            p = pos(it, None)
            if p is None:
                continue
            d = dist(start, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    env = observation.get("environment_name", "") or ""
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        target = max(corners, key=lambda c: dist(c, (ox, oy))) if gw and gh else (0, 0)
        return step_toward((sx, sy), target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("enemy_territory") or []
        target = nearest((sx, sy), targets)
        if target is None:
            gw = observation.get("grid_width", 0) or 0
            gh = observation.get("grid_height", 0) or 0
            if gw and gh:
                target = (gw // 2, gh // 2)
            else:
                target = (ox, oy)
        return step_toward((sx, sy), target)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = nearest((sx, sy), resources)
    if target is not None:
        return step_toward((sx, sy), target)

    # Fallbacks: chase opponent, else stay still.
    if (ox, oy) != (sx, sy):
        return step_toward((sx, sy), (ox, oy))
    return [0, 0]

